<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import type { CrmUnit, CrmPerson, CrmRelation, CrmStaff, CrmPlaybook } from '../../services/personalWorkApi'
import { crmBatchAssignRelations } from '../../services/personalWorkApi'
import FollowupDialog from './FollowupDialog.vue'
import RelationshipLinks from './RelationshipLinks.vue'
import StaffPicker from './StaffPicker.vue'
import PersonFlags from './PersonFlags.vue'
import { authState } from '../../services/authSession'
const props=defineProps<{units:CrmUnit[];people:CrmPerson[];relations:CrmRelation[];staff:CrmStaff[];playbook:CrmPlaybook|null;canWrite:boolean;canRegisterAction:boolean;canBatchAssign:boolean}>()
const emit=defineEmits<{select:[id:string,kind:string];action:[id:string];refresh:[]}>()
const region=ref(''),type=ref(''),query=ref(''),status=ref('all'),importance=ref(''),support=ref(''),selected=ref(''),page=ref(1),unitPage=ref(1),followup=ref('')
const matchesLevel=(value:string|undefined,filter:string)=>!filter||(filter==='__empty__'?!value?.trim():value===filter)
const areas=(u:CrmUnit)=>u.business_regions?.length?u.business_regions:[u.business_region||'未分区']
const regions=computed(()=>[...new Set(props.units.flatMap(areas))])
const regionUnits=computed(()=>props.units.filter(u=>!region.value||areas(u).includes(region.value)))
const types=computed(()=>[...new Set(['主管单位','业主单位','总包单位','设计单位','厂商',...regionUnits.value.map(u=>u.type||'未分类')])])
const staffByKey=computed(()=>new Map(props.staff.map(s=>[s.member_key,s])))
const owner=(r:CrmRelation)=>r.our_member_label||staffByKey.value.get(r.our_member)?.name||r.our_member||'尚未指派'
const canAct=(_r:CrmRelation)=>props.canRegisterAction
const plans=computed(()=>[...(props.playbook?.followups||[])].sort((a,b)=>Number(b.overdue)-Number(a.overdue)||(a.due_date||'9999').localeCompare(b.due_date||'9999')))
const relationsByPerson=computed(()=>{const result=new Map<string,CrmRelation[]>();for(const r of props.relations){const list=result.get(r.person_id)||[];list.push(r);result.set(r.person_id,list)}return result})
const plansByRelation=computed(()=>{const result=new Map<string,CrmPlaybook['followups']>();for(const p of plans.value){const list=result.get(p.relation_id)||[];list.push(p);result.set(p.relation_id,list)}return result})
const rows=computed(()=>props.people.flatMap(person=>{
 const relations=relationsByPerson.value.get(person.id)||[]
 return (relations.length?relations:[undefined]).map(relation=>({person,relation,id:relation?.id||'person:'+person.id,plans:relation?plansByRelation.value.get(relation.id)||[]:[]}))
}))
const isWarning=(r:typeof rows.value[number])=>r.relation?.decay_state==='warning'||r.relation?.decay_state==='alarm'
const baseRows=computed(()=>{
 const ids=new Set(regionUnits.value.filter(u=>!type.value||(u.type||'未分类')===type.value).map(u=>u.id))
 const q=query.value.trim().toLowerCase(),byId=new Map(props.units.map(u=>[u.id,u]))
 return rows.value.filter(r=>ids.has(r.person.unit_id)&&matchesLevel(r.person.importance,importance.value)&&matchesLevel(r.person.support_level,support.value)&&(!q||`${byId.get(r.person.unit_id)?.name} ${byId.get(r.person.unit_id)?.company_full_name||''} ${r.person.name} ${r.person.department||''} ${r.person.title} ${r.relation?owner(r.relation):''} ${r.plans.map(p=>p.next_step).join(' ')}`.toLowerCase().includes(q)))
})
const summary=computed(()=>({people:new Set(baseRows.value.map(r=>r.person.id)).size,warning:baseRows.value.filter(isWarning).length,unassigned:new Set(baseRows.value.filter(r=>!r.relation?.our_member).map(r=>r.person.id)).size,pending:baseRows.value.reduce((n,r)=>n+r.plans.length,0)}))
const filteredRows=computed(()=>baseRows.value.filter(r=>status.value==='all'||(status.value==='warning'?isWarning(r):status.value==='unassigned'?!r.relation?.our_member:r.plans.length>0)))
const groups=computed(()=>{
 const byId=new Map(props.units.map(u=>[u.id,u])),map=new Map<string,typeof rows.value>()
 for(const row of filteredRows.value){const list=map.get(row.person.unit_id)||[];list.push(row);map.set(row.person.unit_id,list)}
 return [...map].map(([id,rows])=>({id,unit:byId.get(id)!,rows,warning:rows.filter(isWarning).length,people:new Set(rows.map(r=>r.person.id)).size})).sort((a,b)=>b.warning-a.warning||a.unit.name.localeCompare(b.unit.name,'zh-CN'))
})
// 客户单位树默认收起，只在用户点开公司根节点后展示下级单位。
const expandedRoots=ref<string[]>([])
const unitTrees=computed(()=>{
 const byId=new Map(props.units.map(unit=>[unit.id,unit]))
 const rootOf=(unit:CrmUnit)=>{let cursor=unit,seen=new Set<string>();while(cursor.parent_unit_id&&byId.has(cursor.parent_unit_id)&&!seen.has(cursor.id)){seen.add(cursor.id);cursor=byId.get(cursor.parent_unit_id)!}return cursor}
 const treeByRoot=new Map<string,{root:CrmUnit;groups:typeof groups.value}>()
 for(const group of groups.value){const root=rootOf(group.unit),tree=treeByRoot.get(root.id)||{root,groups:[]};tree.groups.push(group);treeByRoot.set(root.id,tree)}
 return [...treeByRoot.values()].map(tree=>({...tree,people:tree.groups.reduce((count,group)=>count+group.people,0),warning:tree.groups.reduce((count,group)=>count+group.warning,0)})).sort((a,b)=>b.warning-a.warning||a.root.name.localeCompare(b.root.name,'zh-CN'))
})
const rootCollapsed=(id:string)=>!expandedRoots.value.includes(id)
function toggleRoot(id:string){expandedRoots.value=rootCollapsed(id)?[...expandedRoots.value,id]:expandedRoots.value.filter(item=>item!==id)}
const active=computed(()=>groups.value.find(g=>g.id===selected.value)||groups.value[0])
const visibleRows=computed(()=>active.value?.rows.slice((page.value-1)*12,page.value*12)||[])
const chosen=ref<string[]>([]),batchOpen=ref(false),batchSaving=ref(false),handover=ref(false)
const batchForm=reactive({our_member:'',supervise:true,next_step:'',due_date:'',supervisor:''})
const selectableRows=computed(()=>visibleRows.value.filter(row=>!!row.relation))
const pageAllSelected=computed(()=>!!selectableRows.value.length&&selectableRows.value.every(row=>chosen.value.includes(row.relation!.id)))
function toggleRelation(id:string,checked:boolean){chosen.value=checked?[...new Set([...chosen.value,id])]:chosen.value.filter(item=>item!==id)}
function togglePage(checked:boolean){const ids=selectableRows.value.map(row=>row.relation!.id);chosen.value=checked?[...new Set([...chosen.value,...ids])]:chosen.value.filter(id=>!ids.includes(id))}
function openBatch(){if(!chosen.value.length)return ElMessage.warning('请先勾选需要指派或转移的客情关系');handover.value=false;batchForm.our_member='';batchForm.supervise=true;batchForm.next_step='';batchForm.due_date='';batchForm.supervisor=authState.user?.employee_id||authState.user?.username||'';batchOpen.value=true}
function openBatchFor(id:string){chosen.value=[id];openBatch()}
async function submitBatch(){
 if(!batchForm.our_member&&!batchForm.next_step.trim())return ElMessage.warning('请选择客户对接人或填写维系监督要求')
 if(batchForm.supervise&&!batchForm.next_step.trim())return ElMessage.warning('请填写维系动作监督要求')
 batchSaving.value=true
 try{const result=await crmBatchAssignRelations({relation_ids:chosen.value,transfer:handover.value,...(batchForm.our_member?{our_member:batchForm.our_member}:{}),...(batchForm.supervise?{supervision:{next_step:batchForm.next_step.trim(),due_date:batchForm.due_date||'',supervisor:batchForm.supervisor||''}}:{})});ElMessage.success(handover.value?`已转移 ${result.updated} 条关系及 ${result.plans_transferred||0} 条未完成计划${result.plans_created?`，新增 ${result.plans_created} 条交接监督`:''}`:`已指派 ${result.updated} 条关系，新增 ${result.plans_created} 条维系监督`);batchOpen.value=false;chosen.value=[];emit('refresh')}
 catch(error){ElMessage.error(error instanceof Error?error.message:'批量指派失败')}
 finally{batchSaving.value=false}
}
watch([region,type,query,status],()=>{selected.value='';page.value=1;unitPage.value=1;followup.value=''})
watch(()=>active.value?.id,()=>page.value=1)
watch(()=>props.relations,()=>{page.value=1;unitPage.value=1;followup.value='';chosen.value=[]})
const state=(r?:CrmRelation)=>!r?'未建立关系':r.decay_state==='alarm'?'需尽快维系':r.decay_state==='warning'?'待维系':'正常'
function reset(){region.value='';type.value='';query.value='';status.value='all';importance.value='';support.value=''}
</script>
<template>
<section class="relationship-workbench" aria-label="客户关系工作台">
 <header class="rw-heading"><div><h3>关系统筹</h3><p>先明确谁负责，再安排下一步；人员变化时，可平稳转交关系与未完成计划。</p></div><div class="rw-heading-actions"><span v-if="canBatchAssign" class="rw-selection">已选 {{chosen.length}} 条</span><el-button v-if="canBatchAssign" type="primary" :disabled="!chosen.length" @click="openBatch">批量指派 / 转移</el-button><el-button @click="reset">重置筛选</el-button></div></header>
 <div class="rw-filters"><el-select v-model="region" clearable placeholder="全部区域" aria-label="工作台区域"><el-option v-for="r in regions" :key="r" :label="r" :value="r"/></el-select><el-select v-model="type" clearable placeholder="全部单位类型" aria-label="工作台单位类型"><el-option v-for="t in types" :key="t" :label="t" :value="t"/></el-select><el-select v-model="importance" clearable placeholder="全部重要程度" aria-label="工作台重要程度筛选"><el-option v-for="t in ['重要','一般']" :key="t" :label="t" :value="t"/><el-option label="待补充" value="__empty__"/></el-select><el-select v-model="support" clearable placeholder="全部支持程度" aria-label="工作台支持程度筛选"><el-option v-for="t in ['反对','中立','支持','积极支持']" :key="t" :label="t" :value="t"/><el-option label="待补充" value="__empty__"/></el-select><el-input v-model="query" clearable placeholder="搜索公司全称、联系人、我方人员或跟进事项" aria-label="搜索关系工作台"/></div>
 <div class="rw-summary" aria-label="关系统筹状态筛选"><button :aria-pressed="status==='all'" @click="status='all'"><span>全部联系人</span><b>{{summary.people}}</b></button><button :aria-pressed="status==='unassigned'" class="rw-warning" @click="status='unassigned'"><span>待指派关系</span><b>{{summary.unassigned}}</b><small>优先明确负责人</small></button><button :aria-pressed="status==='pending'" @click="status='pending'"><span>未完成计划</span><b>{{summary.pending}}</b><small>转移时可同步移交</small></button><button :aria-pressed="status==='warning'" @click="status='warning'"><span>维系风险</span><b>{{summary.warning}}</b><small>先确认责任人</small></button></div>
 <div class="rw-flow" aria-label="关系统筹操作指引"><span><b>1</b> 选“待指派”或“维系风险”</span><i>→</i><span><b>2</b> 展开客户单位并勾选关系</span><i>→</i><span><b>3</b> 指派负责人；人员变化时选择转移</span></div>
 <div v-if="groups.length" class="rw-body">
  <aside class="rw-units"><header>客户单位层级 <b>{{groups.length}}</b><small>按公司 → 子单位展开；优先显示维系风险较高的客户</small></header><div class="rw-unit-list"><section v-for="tree in unitTrees" :key="tree.root.id" class="rw-unit-root"><button class="rw-root-toggle" :aria-expanded="!rootCollapsed(tree.root.id)" @click="toggleRoot(tree.root.id)"><span class="rw-root-arrow">{{rootCollapsed(tree.root.id)?'›':'⌄'}}</span><strong>{{tree.root.company_full_name||tree.root.name}}</strong><small>{{tree.people}} 位联系人 <em v-if="tree.warning">{{tree.warning}} 条待维系</em></small></button><div v-show="!rootCollapsed(tree.root.id)" class="rw-unit-children"><button v-for="g in tree.groups" :key="g.id" :aria-pressed="active?.id===g.id" @click="selected=g.id;page=1"><strong>{{g.unit.id===tree.root.id?'总部 / 本级':g.unit.name}}</strong><small>{{areas(g.unit).join(' / ')}} · {{g.unit.type||'未分类'}}</small><span>{{g.people}} 位联系人 <em v-if="g.warning">{{g.warning}} 条待维系</em></span></button></div></section></div></aside>
  <main v-if="active" class="rw-detail"><header><div><h3>{{active.unit.company_full_name||active.unit.name}}</h3><p>{{active.unit.name}} · {{areas(active.unit).join(' / ')}} · {{active.people}} 位联系人 / {{active.rows.length}} 条对接记录</p></div><el-button @click="emit('select',active.id,'unit')">单位详情</el-button></header>
   <RelationshipLinks :relations="(active?.rows||[]).flatMap(r=>r.relation?[r.relation]:[])" :people="people" />
   <div class="rw-table"><table><thead><tr><th v-if="canBatchAssign" class="rw-check"><input type="checkbox" aria-label="全选本页关系" :checked="pageAllSelected" @change="togglePage(($event.target as HTMLInputElement).checked)"/></th><th>客户联系人</th><th>我方对接人</th><th>关系与维系状态</th><th>下一步跟进</th><th>操作</th></tr></thead><tbody><tr v-for="row in visibleRows" :key="row.id"><td v-if="canBatchAssign" class="rw-check"><input v-if="row.relation" type="checkbox" :aria-label="`选择${row.person.name}的关系`" :checked="chosen.includes(row.relation.id)" @change="toggleRelation(row.relation.id,($event.target as HTMLInputElement).checked)"/></td><td><button class="rw-link" @click="emit('select',row.person.id,'person')">{{row.person.name||'姓名待补充'}}</button><small><span :class="{'rw-dim':!row.person.department}">{{row.person.department||'部门待补充'}}</span> · <span :class="{'rw-dim':!row.person.title}">{{row.person.title||'职务待补充'}}</span></small><PersonFlags compact :importance="row.person.importance" :support="row.person.support_level"/></td><td><strong :class="{'rw-dim':!row.relation?.our_staff?.name&&!row.relation?.our_member}">{{row.relation?.our_staff?.name||(row.relation?owner(row.relation):'尚未指派')}}</strong><small><span :class="{'rw-dim':!row.relation?.our_staff?.company}">{{row.relation?.our_staff?.company||'公司待补充'}}</span> / <span :class="{'rw-dim':!row.relation?.our_staff?.department}">{{row.relation?.our_staff?.department||'部门待补充'}}</span> / <span :class="{'rw-dim':!row.relation?.our_staff?.title}">{{row.relation?.our_staff?.title||'岗位待补充'}}</span></small></td><td><span class="rw-state" :class="{'needs-attention':isWarning(row)}">{{state(row.relation)}}</span><small v-if="row.relation">L{{row.relation.strength}} · {{row.relation.days_since_touch==null?'暂无维系日期':`${row.relation.days_since_touch} 天未互动`}}</small><small v-if="row.relation?.single_point_risk">单点对接风险</small></td><td><p class="rw-plan">{{row.plans[0]?.next_step||'暂无待跟进计划'}}</p><small v-if="row.plans.length">{{row.plans[0]?.due_date||'日期待定'}} · 共 {{row.plans.length}} 项</small></td><td><el-button v-if="row.relation&&canBatchAssign" link type="primary" @click="openBatchFor(row.relation.id)">变更负责人</el-button><el-button v-if="row.relation" link @click="followup=row.relation.id">查看跟进</el-button><el-button v-if="row.relation&&canAct(row.relation)" link @click="emit('action',row.relation.id)">登记维系</el-button><el-button v-if="!row.relation" link @click="emit('select',row.person.id,'person')">联系人详情</el-button></td></tr></tbody></table></div>
   <el-pagination v-if="active.rows.length>12" v-model:current-page="page" :page-size="12" :total="active.rows.length" layout="prev, pager, next, total"/>
   <p class="rw-note">一位联系人可由多人对接，分别展示；“暂无计划”不代表已完成。这里仅展示当前授权及上方筛选范围。</p>
  </main>
 </div><el-empty v-else description="当前筛选下暂无匹配的客户关系，可调整区域、类型或状态"/>
 <FollowupDialog v-if="followup" :scope="active?.unit.name||'客户关系'" :followups="plans.filter(p=>filteredRows.some(r=>r.relation?.id===p.relation_id))" :relations="filteredRows.flatMap(r=>r.relation?[r.relation]:[])" :people="people" :units="units" :initial-relation="followup" @close="followup=''" @refresh="emit('refresh')"/>
 <el-dialog v-model="batchOpen" :title="handover ? '关系转移与交接' : '批量关系指派'" width="min(640px,94vw)" append-to-body :close-on-click-modal="false"><p class="rw-batch-tip">已选择 {{chosen.length}} 条客情关系。区域管理员只能提交授权区域内的关系，越区时整批取消。</p><el-form label-position="top"><el-form-item label="处理方式"><el-radio-group v-model="handover"><el-radio :value="false">新增 / 调整指派</el-radio><el-radio :value="true">离职 / 调岗转移</el-radio></el-radio-group></el-form-item><p v-if="handover" class="rw-batch-tip">转移会更换关系负责人，并将该关系下未完成的计划同步移交；历史互动记录保留原负责人，确保留痕完整。</p><el-form-item :label="handover ? '接手客户对接人' : '指派客户对接人（留空则不改变现有指派）'"><StaffPicker v-model="batchForm.our_member"/></el-form-item><el-form-item><el-switch v-model="batchForm.supervise" :active-text="handover ? '同时创建交接确认任务' : '同时配置维系动作监督'"/></el-form-item><template v-if="batchForm.supervise"><el-form-item :label="handover ? '交接要求' : '维系要求'" required><el-input v-model="batchForm.next_step" type="textarea" :rows="3" :placeholder="handover ? '例如：与原负责人完成背景、关键人和待办交接，确认首访时间' : '例如：本周完成首次拜访，上传纪要并确认下一步计划'"/></el-form-item><div class="rw-supervision-grid"><el-form-item label="截止日期（选填）"><el-date-picker v-model="batchForm.due_date" type="date" value-format="YYYY-MM-DD" clearable style="width:100%"/></el-form-item><el-form-item label="监督人"><StaffPicker v-model="batchForm.supervisor"/></el-form-item></div></template></el-form><template #footer><el-button @click="batchOpen=false">取消</el-button><el-button type="primary" :loading="batchSaving" @click="submitBatch">{{ handover ? '确认转移并交接' : '确认批量指派' }}</el-button></template></el-dialog>
</section>
</template>
